<?php require '../includes/functions.php'; if(user()){header('Location: '.url('app.php'));exit;} $err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6)$err='Completa los datos. La contraseña debe tener mínimo 6 caracteres.';else{try{$st=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Cuenta creada. Ya puedes ingresar.');header('Location: '.url('auth/login.php'));exit;}catch(PDOException $e){$err='Ese correo ya está registrado.';}}}$title='Crear cuenta';require '../includes/header.php';?><main class="auth-wrap"><form class="auth-card" method="post"><div class="auth-logo"><img src="<?=url('assets/img/logo.png')?>"></div><h1>Crea tu cuenta</h1><p>Únete a la comunidad de Encuéntralo.</p><?php if($err):?><div class="flash err"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Nombre completo</label><input class="input" name="name" required><label>Correo electrónico</label><input class="input" type="email" name="email" required><label>Contraseña</label><input class="input" type="password" name="password" minlength="6" required><label><input type="checkbox" required> Acepto el tratamiento de datos para el funcionamiento del servicio.</label><button class="btn primary" style="width:100%;margin-top:16px">Crear cuenta</button><p class="small">¿Ya tienes cuenta? <a href="<?=url('auth/login.php')?>"><b>Ingresar</b></a></p></form></main><?php require '../includes/footer.php';?>